def transform(grid):
    g = np.array(grid)
    n = min(g.shape)
    order = []
    for i in range((n + 1) // 2):
        c = int(g[i, i])
        if c not in order:
            order.append(c)
    k = len(order)
    mapping = {order[i]: order[(i - 1) % k] for i in range(k)}
    out = g.copy()
    for c in order:
        out[g == c] = mapping[c]
        emit(out, f"Recolour every cell of colour {c} to {mapping[c]} (each ring takes the colour of the ring just outside it; the outer frame takes the innermost colour).")
    emit(out, "Final grid: the ring colours have rotated one step outward.")
    return out
